def compute(vars):
    net_assets = vars["Net Assets"]
    total_assets = vars["Total Assets"]
    total_liabilities = -net_assets + total_assets
    return {
        "value": total_liabilities,
        "trace": {
            "Net Assets": net_assets,
            "Total Assets": total_assets,
            "output_meta": {
                "currency": "$",
                "scale": "millions",
                "unit": None
            }
        }
    }
